Tool response:
Tool: find_applications_missing_required_documents
Description: Returns application IDs and their missing document types for applications that were submitted within the last 7 days and are missing at least one required document.
Parameters:
    {
      "type": "object",
      "properties": {
        "days_back": {
          "type": "integer",
          "description": "Number of days back to consider for submission date (default: 7)",
          "default": 7,
          "title": "Days Back"
        }
      },
      "required": []
    }
